import{_ as t,o as a,c as r,ai as n}from"./chunks/framework.C33Uq6m-.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/index.md","filePath":"fr/guide/index.md"}'),s={name:"fr/guide/index.md"};function o(i,e,l,d,u,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><strong>LLMxRay</strong> est un tableau de bord gratuit et local-first qui se connecte à <a href="https://ollama.com" target="_blank" rel="noreferrer">Ollama</a> sur votre machine. Il vous permet de discuter avec n&#39;importe quel modèle téléchargé puis d&#39;inspecter tout ce qui s&#39;est passé en coulisses : la vitesse d&#39;arrivée de chaque token, ce que le modèle a pu &quot;penser&quot;, comment différents paramètres modifient la sortie, et bien plus encore.</p><p><strong>Pas de cloud. Pas de clés API. Aucun coût.</strong> Tout s&#39;exécute sur votre matériel.</p><h2 id="a-qui-s-adresse-llmxray" tabindex="-1">À qui s&#39;adresse LLMxRay ? <a class="header-anchor" href="#a-qui-s-adresse-llmxray" aria-label="Permalink to &quot;À qui s&#39;adresse LLMxRay ?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Vous êtes...</th><th>LLMxRay vous aide à...</th></tr></thead><tbody><tr><td><strong>Débutant curieux</strong></td><td>Voir les réponses de l&#39;IA se former en temps réel et comprendre ce que signifient vraiment &quot;température&quot; ou &quot;tokens&quot;</td></tr><tr><td><strong>Étudiant / enseignant</strong></td><td>Explorer visuellement le comportement des modèles -- idéal pour les cours et démonstrations en IA/ML</td></tr><tr><td><strong>Développeur</strong></td><td>Déboguer les prompts, comparer les modèles, profiler la latence, inspecter les appels d&#39;outils</td></tr><tr><td><strong>Chercheur</strong></td><td>Mener des expériences contrôlées : même prompt, paramètres différents, résultats côté à côté</td></tr></tbody></table><h2 id="navigation-dans-l-application" tabindex="-1">Navigation dans l&#39;application <a class="header-anchor" href="#navigation-dans-l-application" aria-label="Permalink to &quot;Navigation dans l&#39;application&quot;">​</a></h2><p>LLMxRay dispose d&#39;une barre latérale avec 10 éléments de navigation, chacun représentant une fonctionnalité majeure. Ce guide comporte un chapitre par élément, dans l&#39;ordre exact d&#39;apparition dans la barre latérale :</p><ol><li><strong><a href="./chat-diagnostics.html">Diagnostics de Chat</a></strong> -- L&#39;interface de chat principale avec streaming et analyse de session</li><li><strong><a href="./compare.html">Comparer</a></strong> -- Comparaison côté à côté de modèles et de paramètres</li><li><strong><a href="./embeddings.html">Plongements</a></strong> -- Visualisation d&#39;embeddings textuels et similarité</li><li><strong><a href="./knowledge-base.html">Base de Connaissances</a></strong> -- Téléchargement de documents, découpage et recherche RAG</li><li><strong><a href="./tool-workshop.html">Atelier d&#39;Outils</a></strong> -- Constructeur visuel d&#39;outils avec synchronisation du code</li><li><strong><a href="./ai-training.html">Entraînement IA</a></strong> -- Curation et export de données d&#39;entraînement</li><li><strong><a href="./models.html">Modèles</a></strong> -- Navigateur de modèles et détection des capacités</li><li><strong><a href="./benchmark.html">Benchmark</a></strong> -- Évaluation standardisée des modèles avec logprobs</li><li><strong><a href="./system.html">Mon Système</a></strong> -- Détection du matériel et statut d&#39;Ollama</li><li><strong><a href="./settings.html">Paramètres</a></strong> -- Connexion, paramètres et préférences</li></ol><h2 id="autres-elements" tabindex="-1">Autres éléments <a class="header-anchor" href="#autres-elements" aria-label="Permalink to &quot;Autres éléments&quot;">​</a></h2><ul><li><strong>Barre d&#39;en-tête</strong> -- Affiche le titre de la page courante, un bouton de thème (sombre/clair) et le statut de connexion à Ollama (vert = connecté, rouge = déconnecté).</li><li><strong>Bouton de retour d&#39;expérience</strong> -- En bas de la barre latérale. Ouvre une fenêtre superposée pour soumettre directement vos commentaires.</li></ul><h2 id="etapes-suivantes" tabindex="-1">Étapes suivantes <a class="header-anchor" href="#etapes-suivantes" aria-label="Permalink to &quot;Étapes suivantes&quot;">​</a></h2><p>Si vous n&#39;avez pas encore installé LLMxRay, rendez-vous sur la page <a href="./installation.html">Installation</a>. Sinon, choisissez n&#39;importe quel chapitre dans la barre latérale pour commencer à explorer.</p>',12)])])}const h=t(s,[["render",o]]);export{p as __pageData,h as default};
